"""Browser repair, login, required controls and complete SQL preview acceptance."""
import json

from test_acceptance_browser import browser, engine_url, isolated_url, pytestmark
from test_acceptance_browser_mapping import HELPERS, counted_source, count, durable_runs


def test_browser_saved_validation_survives_reopen_and_targets_repair(isolated_url):
    browser(isolated_url, HELPERS+r"""
 const w=await seed({nodes:[node('q',{kind:'sql',source:'SELECT 1',config:{dialect:'sqlite'}}),node('p',{inputs:{orders:{source:'node',node_id:'missing',path:['rows']}}})],edges:[]});await open(w);
 await page.locator('.wf-validation button').filter({hasText:'q'}).first().waitFor();assert.ok((await page.locator('.wf-validation').textContent()).includes('orders'));await page.locator('.wf-validation button').filter({hasText:'orders'}).first().click();assert.ok((await page.locator('article[data-node-id="p"]').getAttribute('class')).includes('selected'));assert.equal(await page.getByRole('button',{name:'Inputs',exact:true}).getAttribute('class').then(v=>v.includes('active')),true);assert.ok((await page.locator('.wf-validation').textContent()).includes('orders'));
 await page.reload();await page.locator('.wf-validation').waitFor();const rejected=page.waitForResponse(r=>r.url().endsWith('/publish'));await page.getByRole('button',{name:'Publish',exact:true}).click();assert.equal((await rejected).status(),422);assert.equal((await request('/api/workflows/'+w.id)).published_version_id,null);
 const c=await request('/api/connections','POST',{name:'Repair local',dialect:'sqlite',config:{synthetic:true}});await open(w);await selectNode('q');await page.getByLabel('Connection',{exact:true}).selectOption(c.id);await selectNode('p');await page.getByRole('button',{name:'Inputs',exact:true}).click();await page.locator('.wf-binding').getByRole('button',{name:'Configuration',exact:true}).click();await page.getByLabel('Source',{exact:true}).selectOption('constant');await page.getByLabel('Value (JSON or text)',{exact:true}).fill('[]');await page.getByRole('button',{name:'Map input',exact:true}).click();let saved=await save(w);assert.equal(saved.validation_errors.length,0);assert.equal(await page.locator('.wf-validation').count(),0);const published=page.waitForResponse(r=>r.url().endsWith('/publish'));await page.getByRole('button',{name:'Publish',exact:true}).click();const v=await(await published).json();assert.ok(v.version_id);await page.locator('.wf-editor-head').getByText('Published',{exact:true}).waitFor();assert.ok((await page.locator('.wf-save-state').textContent()).includes('Draft saved'));assert.equal(await page.locator('article[data-node-id="p"]').getByText('Ready',{exact:true}).count(),1);const prior=(await request('/api/workflows/'+w.id)).nodes.find(n=>n.id==='p').source;await sourceCode('p','def main(inputs): return {"edited":True}');assert.ok((await page.locator('.wf-save-state').textContent()).includes('Unsaved'));assert.equal((await request('/api/workflows/'+w.id)).published_version_id,v.version_id);assert.equal((await request('/api/workflows/'+w.id)).nodes.find(n=>n.id==='p').source,prior);assert.deepEqual(await request('/api/workflow-runs'),[]);
 """)


def test_browser_publication_only_error_keeps_node_target(isolated_url):
    browser(isolated_url, HELPERS+r"""
 const w=await seed({nodes:[node('p',{config:{runtime_version_id:'missing-runtime-version'}})],edges:[]});await open(w);const pending=page.waitForResponse(r=>r.url().endsWith('/publish'));await page.getByRole('button',{name:'Publish',exact:true}).click();assert.equal((await pending).status(),422);await page.locator('.wf-validation button').filter({hasText:'p'}).first().click();assert.ok((await page.locator('article[data-node-id="p"]').getAttribute('class')).includes('selected'));assert.ok((await page.locator('.wf-validation').textContent()).length>20);assert.equal((await request('/api/workflows/'+w.id)).published_version_id,null);
 """)


def test_browser_delete_source_undo_and_explicit_rebind_preserve_other_inputs(isolated_url):
    browser(isolated_url, HELPERS+r"""
 const {id,...template}=(await request('/api/workflow-templates'))[0],sql=template.nodes.find(n=>n.id==='orders');template.nodes.push({...structuredClone(sql),id:'replacement',name:sql.name});template.nodes.find(n=>n.id==='summary').inputs.keep={source:'constant',value:false};const w=await seed(template);await open(w);const before=await save(w);await selectNode('orders');await page.locator('.wf-outline-row.selected').getByRole('button',{name:'Delete node',exact:true}).click();await page.getByRole('button',{name:'Delete from draft',exact:true}).click();await selectNode('summary');await page.getByRole('button',{name:'Inputs',exact:true}).click();assert.ok((await page.locator('.wf-binding').filter({hasText:'orders'}).textContent()).includes('Source node was deleted'));let saved=await save(w);assert.equal(saved.nodes.some(n=>n.id==='orders'),false);assert.equal(saved.edges.some(e=>e.source==='orders'||e.target==='orders'),false);assert.equal(saved.nodes.find(n=>n.id==='summary').inputs.orders.node_id,'orders');const rejected=page.waitForResponse(r=>r.url().endsWith('/publish'));await page.getByRole('button',{name:'Publish',exact:true}).click();assert.equal((await rejected).status(),422);assert.ok((await page.locator('.wf-validation').textContent()).includes('orders'));
 await page.getByRole('button',{name:'Undo',exact:true}).click();saved=await save(w);assert.deepEqual(saved.nodes.find(n=>n.id==='orders'),before.nodes.find(n=>n.id==='orders'));assert.deepEqual(saved.nodes.find(n=>n.id==='summary').inputs,before.nodes.find(n=>n.id==='summary').inputs);await selectNode('summary');await page.getByRole('button',{name:'Inputs',exact:true}).click();await page.locator('.wf-binding').filter({has:page.locator('strong').filter({hasText:/^orders$/})}).getByRole('button',{name:'Configuration',exact:true}).click();await page.getByLabel('Upstream output',{exact:true}).selectOption('replacement');await page.getByLabel('Output field',{exact:true}).selectOption('["rows"]');await page.getByRole('button',{name:'Map input',exact:true}).click();saved=await save(w);assert.equal(saved.nodes.find(n=>n.id==='summary').inputs.orders.node_id,'replacement');assert.deepEqual(saved.nodes.find(n=>n.id==='summary').inputs.keep,{source:'constant',value:false});assert.deepEqual(saved.nodes.find(n=>n.id==='report').inputs,before.nodes.find(n=>n.id==='report').inputs);await open(w);assert.equal((await request('/api/workflows/'+w.id)).nodes.find(n=>n.id==='summary').inputs.orders.node_id,'replacement');
 """)


def test_browser_default_account_exact_fill_is_conditional_and_never_submits(isolated_url):
    browser(isolated_url,r"""
 const fresh=await browser.newContext({locale:'zh-CN'}),login=await fresh.newPage();try{await login.goto(origin);const boot=await login.evaluate(async()=>await(await fetch('/api/bootstrap')).json());assert.ok(boot.local_account);assert.equal(await login.locator('html').getAttribute('lang'),'en');let submissions=0;login.on('request',r=>{if(r.url().endsWith('/api/login'))submissions++;});await login.getByRole('button',{name:'Use default account',exact:true}).click();assert.equal(await login.locator('[name=username]').inputValue(),boot.local_account.username);assert.equal(await login.locator('[name=password]').inputValue(),boot.local_account.password);assert.equal(submissions,0);await login.locator('[data-locale="zh-CN"]').click();assert.ok((await login.locator('.wf-default-account').textContent()).includes('默认本地账户'));await login.getByRole('button',{name:'使用默认账户',exact:true}).click();assert.equal(submissions,0);assert.equal(await login.locator('[name=password]').inputValue(),boot.local_account.password);await login.locator('[data-locale="en"]').click();await login.getByRole('button',{name:'Sign in',exact:true}).click();await login.getByRole('button',{name:'New workflow',exact:true}).waitFor();assert.equal(submissions,1);}finally{await fresh.close();}
 const absent=await browser.newContext(),other=await absent.newPage();try{await other.route('**/api/bootstrap',async route=>{const response=await route.fetch(),body=await response.json();body.local_account=null;await route.fulfill({response,json:body});});await other.goto(origin);assert.equal(await other.locator('.wf-default-account').count(),0);assert.equal(await other.locator('[name=username]').inputValue(),'');assert.equal(await other.locator('[name=password]').inputValue(),'');assert.ok((await request('/api/bootstrap')).local_account);}finally{await absent.close();}
 """)


def test_browser_schedule_required_controls_block_empty_values_without_mutation(isolated_url):
    browser(isolated_url,r"""
 const w=await seed({nodes:[node('p')],edges:[]});await open(w);await page.getByRole('button',{name:'Triggers',exact:true}).click();const original=await request('/api/workflows/'+w.id);let previews=0;page.on('request',r=>{if(r.url().endsWith('/preview'))previews++;});
 for(const [kind,label] of [['interval','Every'],['interval','Starting anchor'],['daily','Time'],['once','Date'],['daily','Timezone']]){await page.getByLabel('Schedule',{exact:true}).selectOption('manual');await page.getByLabel('Schedule',{exact:true}).selectOption(kind);await page.getByLabel('Timezone',{exact:true}).fill('UTC');const input=page.getByLabel(label,{exact:true});assert.equal(await input.getAttribute('required'),'');await input.fill('');const rejected=page.waitForResponse(r=>r.url().endsWith('/preview'));await page.getByRole('button',{name:'Preview next five',exact:true}).click();assert.ok([400,422].includes((await rejected).status()));assert.ok(await input.evaluate(el=>!el.checkValidity()&&el.validationMessage.length>0));await page.getByRole('button',{name:'Save draft',exact:true}).last().click();assert.deepEqual((await request('/api/workflows/'+w.id)).schedule,original.schedule);}
 await page.getByLabel('Timezone',{exact:true}).fill('UTC');await page.getByLabel('Multiple times (optional)',{exact:true}).fill('07:00, 18:00');await page.getByLabel('Time',{exact:true}).fill('');const pending=page.waitForResponse(r=>r.url().endsWith('/preview'));await page.getByRole('button',{name:'Preview next five',exact:true}).click();assert.equal((await pending).status(),200);
 """)


def test_browser_205_rows_and_empty_preview_keep_complete_n8n_inputs(engine_url,tmp_path):
    counter=tmp_path/'consumer-count.txt'
    source=counted_source(counter,"{'count':len(inputs['orders']),'last':inputs['orders'][-1] if inputs['orders'] else None}")
    browser(engine_url,HELPERS+'const source='+json.dumps(source)+';'+r"""
 const {id,...template}=(await request('/api/workflow-templates'))[0];template.nodes=template.nodes.filter(n=>n.id!=='report');template.edges=template.edges.filter(e=>e.target!=='report');const q=template.nodes.find(n=>n.id==='orders'),p=template.nodes.find(n=>n.id==='summary');q.source="WITH RECURSIVE data(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM data WHERE n<205) SELECT n, CASE WHEN n=205 THEN 'final-sentinel' ELSE 'row' END AS marker FROM data ORDER BY n";p.source=source;p.outputs={};const w=await seed(template);await open(w);let run=await testRun(w);assert.equal(run.status,'succeeded',run.error);assert.equal(run.nodes.summary.inputs.orders.length,205);assert.deepEqual(run.nodes.summary.output.data,{count:205,last:{n:205,marker:'final-sentinel'}});assert.deepEqual(run.nodes.summary.inputs.orders,run.nodes.orders.output.data.rows);await page.goto(origin+'/workflow-runs/'+run.id);const sql=page.locator('.wf-node-detail').filter({has:page.locator('summary strong').filter({hasText:q.name})});await sql.locator('summary').first().click();await sql.getByText('Paginated data preview',{exact:true}).click();await sql.getByRole('button',{name:'Load preview',exact:true}).click();await sql.getByText('1–100 / 205',{exact:true}).waitFor();await sql.getByRole('button',{name:'Next page',exact:true}).click();await sql.getByText('101–200 / 205',{exact:true}).waitFor();await sql.getByRole('button',{name:'Next page',exact:true}).click();await sql.getByText('201–205 / 205',{exact:true}).waitFor();assert.ok((await sql.locator('table').textContent()).includes('final-sentinel'));assert.equal(await sql.getByRole('button',{name:'Next page',exact:true}).count(),0);const py=page.locator('.wf-node-detail').filter({has:page.locator('summary strong').filter({hasText:p.name})});await py.locator('summary').first().click();assert.ok((await py.locator('.wf-detail-grid section').first().textContent()).includes('final-sentinel'));
 await open(w);await sourceCode('orders','SELECT 1 AS n WHERE 0');run=await testRun(w);assert.equal(run.status,'succeeded',run.error);assert.deepEqual(run.nodes.summary.inputs,{orders:[]});assert.deepEqual(run.nodes.summary.output.data,{count:0,last:null});await page.goto(origin+'/workflow-runs/'+run.id);const empty=page.locator('.wf-node-detail').filter({has:page.locator('summary strong').filter({hasText:q.name})});await empty.locator('summary').first().click();await empty.getByText('Paginated data preview',{exact:true}).click();await empty.getByRole('button',{name:'Load preview',exact:true}).click();await empty.getByText('0–0 / 0',{exact:true}).waitFor();assert.equal(await empty.getByRole('button',{name:'Next page',exact:true}).count(),0);
 """)
    assert count(counter)==['invoked']*2
    assert len(durable_runs(tmp_path))==2
